import os
import unicodedata
from pathlib import PurePosixPath
from flask import Flask, request, send_file, abort, session
from functools import wraps
import hashlib
import hmac
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

BASE_DIR = '/srv/user_files'
ALLOWED_EXTENSIONS = {'.txt', '.pdf', '.png', '.jpg', '.doc'}

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        if 'user_id' not in session:
            abort(401)
        return f(*args, **kwargs)
    return decorated

def sanitize_filename(filename):
    """Sanitize filename to prevent directory traversal.
    Uses NFKC normalization for consistent Unicode handling."""
    # Normalize Unicode to canonical form FIRST before any checks
    # This prevents bypass via non-normalized Unicode sequences
    normalized = unicodedata.normalize('NFKC', filename)

    # After normalization, check for traversal sequences
    if '..' in normalized or '/' in normalized or '\\' in normalized:
        return None

    # Reject any path separators
    if os.sep in normalized or os.altsep and os.altsep in normalized:
        return None

    # Validate extension
    _, ext = os.path.splitext(normalized)
    if ext.lower() not in ALLOWED_EXTENSIONS:
        return None

    # Additional safety: ensure no null bytes
    if '\x00' in normalized:
        return None

    # Ensure it's just a filename, no directory components
    if normalized != os.path.basename(normalized):
        return None

    return normalized

def resolve_user_path(user_id, filename):
    """Resolve the full path for a user's file.
    Each user has their own subdirectory."""
    user_dir = os.path.join(BASE_DIR, f'user_{user_id}')

    # Ensure user directory exists
    os.makedirs(user_dir, exist_ok=True)

    # Build the full path
    full_path = os.path.join(user_dir, filename)

    return full_path

def validate_path_safety(full_path, user_id):
    """Validate that the resolved path is within the user's directory.
    Uses os.path.realpath to resolve symlinks and canonicalize."""
    expected_prefix = os.path.realpath(os.path.join(BASE_DIR, f'user_{user_id}'))

    # Use realpath to resolve ALL symlinks and relative components
    real_path = os.path.realpath(full_path)

    # Check that the real path starts with the expected prefix
    # Use os.sep to prevent prefix confusion (user_1 vs user_10)
    if not real_path.startswith(expected_prefix + os.sep) and real_path != expected_prefix:
        return False

    return True

@app.route('/files/download')
@require_auth
def download_file():
    """Download a file from the user's directory."""
    filename = request.args.get('name', '')
    if not filename:
        abort(400)

    user_id = session['user_id']

    # Sanitize the filename
    safe_name = sanitize_filename(filename)
    if safe_name is None:
        abort(400, 'Invalid filename')

    # Resolve the full path
    full_path = resolve_user_path(user_id, safe_name)

    # Validate path is within user's directory
    if not validate_path_safety(full_path, user_id):
        abort(403, 'Access denied')

    # Serve the file
    if not os.path.isfile(full_path):
        abort(404)

    return send_file(full_path)

@app.route('/files/upload', methods=['POST'])
@require_auth
def upload_file():
    """Upload a file to the user's directory."""
    if 'file' not in request.files:
        abort(400)

    file = request.files['file']
    filename = file.filename

    if not filename:
        abort(400)

    user_id = session['user_id']

    # Sanitize the filename
    safe_name = sanitize_filename(filename)
    if safe_name is None:
        abort(400, 'Invalid filename')

    # Resolve the full path
    full_path = resolve_user_path(user_id, safe_name)

    # Validate path is within user's directory
    if not validate_path_safety(full_path, user_id):
        abort(403, 'Access denied')

    # Save the file
    file.save(full_path)

    return {'status': 'uploaded', 'filename': safe_name}, 201

@app.route('/files/list')
@require_auth
def list_files():
    """List files in the user's directory."""
    user_id = session['user_id']
    user_dir = os.path.join(BASE_DIR, f'user_{user_id}')

    os.makedirs(user_dir, exist_ok=True)

    files = []
    for f in os.listdir(user_dir):
        filepath = os.path.join(user_dir, f)
        if os.path.isfile(filepath):
            files.append({
                'name': f,
                'size': os.path.getsize(filepath)
            })

    return {'files': files}

if __name__ == '__main__':
    app.run(host='127.0.0.1', port=5000)
